syntax = "proto3";

package acme.gateway.common;

message Timestamp {
  int64 seconds = 1;
  int32 nanos = 2;
}

message Error {
  int32 code = 1;
  string message = 2;
}

=== gateway.proto ===
syntax = "proto3";

package acme.gateway.v1;

import "common.proto";

message RouteRequest {
  string route_id = 1;
  bytes payload = 2;
  acme.gateway.common.Timestamp sent_at = 3;
}

message RouteReply {
  bool accepted = 1;
  acme.gateway.common.Error error = 2;
}

service Gateway {
  rpc Route(RouteRequest) returns (RouteReply);
}

